create or replace function public.erp_assign_hr_manager_permission_template() returns trigger language plpgsql set search_path=public as $$ declare linked_template_name text; begin if trim(coalesce(new.job_title,''))='مدير موارد بشرية' then select t.id into new.permission_template_id from public.erp_permission_templates t where t.company_id=new.company_id and t.name_ar='مدير موارد بشرية' and t.is_active=true limit 1; else select t.name_ar into linked_template_name from public.erp_permission_templates t where t.id=new.permission_template_id and t.company_id=new.company_id; if linked_template_name='مدير موارد بشرية' then new.permission_template_id:=null; end if; end if; return new; end; $$;